// Monta UMA consulta GraphQL por loja com ordersCount por dia (fuso -03:00), criados e pagos.
// `dias` = quantos dias para tras (3 no diario; subir para 62 numa execucao manual de backfill).
const dias = Number($input.first().json.dias || 3);
const LOJAS = [
  { marca: 'aristocrata', dominio: 'gwx20u-vw.myshopify.com' },
  { marca: 'fishermans',  dominio: 'c0kfm1-qt.myshopify.com' },
];
const sp = new Date(Date.now() - 3 * 3600 * 1000);
const ymd = (d) => d.toISOString().slice(0, 10);
const out = [];
for (const loja of LOJAS) {
  const campos = []; const mapa = [];
  for (let i = 0; i < dias; i++) {
    const d = new Date(sp); d.setUTCDate(d.getUTCDate() - i);
    const dia = ymd(d); const prox = new Date(d); prox.setUTCDate(prox.getUTCDate() + 1);
    const faixa = `created_at:>='${dia}T00:00:00-03:00' AND created_at:<'${ymd(prox)}T00:00:00-03:00'`;
    campos.push(`t${i}: ordersCount(query: ${JSON.stringify(faixa)}) { count precision }`);
    campos.push(`p${i}: ordersCount(query: ${JSON.stringify(faixa + ' AND financial_status:paid')}) { count precision }`);
    mapa.push({ i, dia });
  }
  out.push({ json: { marca: loja.marca, url: `https://${loja.dominio}/admin/api/2025-07/graphql.json`,
    body: { query: `{ ${campos.join(' ')} }` }, mapa } });
}
return out;

// Transforma a resposta em linhas (marca, dia, pedidos, pedidos_pagos) e num upsert.
const q = (v) => v === null || v === undefined ? 'NULL' : typeof v === 'number' ? String(v) : "'" + String(v).replace(/'/g, "''") + "'";
const vals = [];
for (const item of $input.all()) {
  const meta = $('Monta GraphQL').itemMatching($input.all().indexOf(item)).json;
  const data = (item.json.data) || {};
  if (item.json.errors) throw new Error('Shopify GraphQL: ' + JSON.stringify(item.json.errors).slice(0, 300));
  for (const { i, dia } of meta.mapa) {
    const t = data['t' + i], p = data['p' + i];
    if (!t) continue;                      // sem resposta para o dia: nao grava (NULL, nunca 0)
    vals.push('(' + [meta.marca, dia, t.count, p ? p.count : null].map(q).join(',') + ')');
  }
}
if (!vals.length) return [{ json: { sql: 'SELECT 0 AS nada' } }];
return [{ json: { sql: `INSERT INTO cx_pedido_dia (marca, dia, pedidos, pedidos_pagos) VALUES ${vals.join(',')}
  ON CONFLICT (marca, dia) DO UPDATE SET pedidos=EXCLUDED.pedidos, pedidos_pagos=EXCLUDED.pedidos_pagos, coletado_em=now()`, linhas: vals.length } }];
